SELECT CASE WHEN amount >= 3300 THEN 'LARGE' ELSE 'SMALL' END AS amount_tier, DATE_TRUNC('WEEK', txn_time) AS week_start, COUNT(*) FILTER (WHERE txn_type = 'FEE') AS fee_rows, COUNT(DISTINCT account_id) AS distinct_account_ids, COUNT(DISTINCT id) AS distinct_ids FROM transactions GROUP BY GROUPING SETS ((CASE WHEN amount >= 3300 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('WEEK', txn_time)), (CASE WHEN amount >= 3300 THEN 'LARGE' ELSE 'SMALL' END), ()) HAVING distinct_ids > 1 ORDER BY distinct_ids DESC NULLS FIRST
